-- The psionic half of step 2 of the Nightbane extraction plan
-- (apps/character-creator/docs/surveys/nightbane-core.md). Printed 69-84.
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/zzzzzzzzzzzzz-nb-psionics.sql
--
-- THE BOOK DESCRIBES 54 PSYCHIC ABILITIES (45 names; ten are described in two
-- sections) AND THIS FILE ADDS THREE. Every stat block was compared with the live
-- catalog: 42 match on cost, and the three `Varies` kinesis powers match the
-- catalog's own variable costs. The three written here have no catalog row:
--   Divination                  Sensitive  3 I.S.P.   printed 72-73
--   Mediumship/Clairsentience   Sensitive  4 I.S.P.   printed 74-75
--   Induce Pain                 Healing    2 per min  printed 83-84
-- Each stat block was read off the page, not taken from the extraction. The
-- heading prints `Mediumship/Clairsentience (Seance)`; the stored name is the
-- index's (printed 69). Heroes Unlimited tagged its new powers with its game, and
-- these follow: `system = 'nightbane'`. The book's Healer section is the
-- catalog's `Healing` category.
--
-- DIVINATION AND MEDIUMSHIP PRINT A "BASE SKILL" (42% +2%, and 30% +2% per
-- P.P.E. point drawn on) - a roll, not a cost. psionic_powers has no column for
-- it; it stays in the description, which carries the full entry.
--
-- NOT WRITTEN, and why (the survey's D7 records the reasoning):
--   * Healing - named on printed 69's list and described nowhere in the chapter.
--   * Suggestion - resolves to the existing `Hypnotic Suggestion`.
--   * Death Trance prints 2 I.S.P. as a Sensitive power and 1 as a Physical one;
--     the catalog holds 1. A power's cost per category has no home - the psionic
--     half of BOOK-INGEST-AUDIT F102 - so the existing row is left alone.

INSERT INTO psionic_powers
  (name, category, isp, isp_note, variant_note, source, source_book, system, range, duration, saving_throw, description, min_tier)
VALUES
  ('Divination', 'Sensitive', 3, NULL, NULL, 'import', 'Nightbane RPG p.72-73', 'nightbane', 'Self', '2D4 minutes', NULL, 'Divination is a precognitive ability to sense the future. Throughout the history of the world there have been fortunetellers who claim to foretell the future by reading tarot cards, sticks, palms, tea leaves and other things. This precognitive power is much less accurate and detailed than clairvoyance. With divination there is no image, no sound, no tangible memory or flash, only an impression. To perform a divination, the diviner must meditate for at least 15 or 20 minutes. The tools or item(s) read by the fortuneteller are laid out/spilled before the psychic, their random patterns providing hints to the future. No specific questions or details can be revealed, such as, "Yes, if you go to the house this evening you will be attacked by a madman and murdered with a knife." Instead, what might be revealed is something like, "I see the specter of death. It waits hungrily. I see violence and yes, madness." or "Death awaits you at the house." Neither says that the character will be killed, but does confirm that somebody or something may be out to kill him. This is the way divination should work, small impressions of the possible future. The game master should never predetermine the outcome of a game or an event within a game. Like real life, there are too many x-factors which can change what may seem inevitable. Consequently, keep the divination answers a bit general to give yourself maximum flexibility of play. NEVER make a situation completely hopeless! The diviner can try to divinate his own future, but with a -10% skill penalty, or the future of ONE person at a time. The person can ask up to 13 questions which the diviner will try to answer. The divining character must roll percentile dice for each question. A failed roll means he senses nothing and cannot answer the question. Professional fortunetellers will make up some intriguing line of malarkey like, "The wheels of the future are always turning. Too many things could influence your future in this regard (in answer to the question). Proceed with caution." or "Something blocks my vision. I can tell you nothing." There are all types of methods and items of divination. The psychic''s personal orientation/focus must be limited to one or two types. Select one (or two maximum) focuses/objects needed for divination. Note: The character cannot see into the future without using the item(s). DIVINATION FORMS TABLE ARITHMANCY: The use of numbers, either in patterns which reoccur around the person or selected randomly, to tell their past or predict their future. See also Numerology. ASTRAGALOMANCY: Divination by the use of dice or marked pieces of bone. This technique includes modem dice, the Viking system of "casting the runes" and the casting of human and animal knucklebones used by African witch doctors. BELOMANCY: Foretelling the future by throwing arrows to the ground and observing the pattern they form. This particular technique would be well suited to primitive or modem, bow-using cultures. CARTOMANCY: This form of divination is done literally by the "tum of a card." It uses special decks of cards, known as Tarot, but can also be done with a regular deck of playing cards. Each card is ascribed a specific meaning and are laid in a pattern. Meditation on the cards and the pattern they form give the divination. Cartomancy has always been one of the most popular kinds of fortunetelling and has existed from the time of the Pharaohs of Egypt. CEPHALOMANCY: This divinatory skill uses the bumps and depressions which can be found on a person''s skull to predict their future. It is vaguely related to palmistry in that the person''s entire future is supposed to be written on their body. CHIROMANCY: Also known as palmistry, this art teaches the user to read the future in the lines found in the palms of the questioner''s hands. Each line is supposed to govern one particular area of life, including Life, Love and Fortune. CRYSTALOMANCY: Another very common form of divination, this technique uses a crystal ball as an aid for seeing into the future. There are many arguments among experts as to whether the answers/visions actually appear within the crystal or just within the mind of the seer, who uses the crystal only as a focus. EMPROMANCY: This is divination by the studying of objects placed in a sacrificial fire, especially as to any shapes or forms seen in the smoke or the fire itself. GEOMANCY: Divination by tossing pebbles on the ground and analyzing the pattern they form. The pebbles can either be special ceremonial stones, or they can simply be a handful of stones picked up on a beach. HYDROMANCY: This skill requires the use of a small pool of water in which the seer analyzes the ripples and other disturbances of the pool itself. ICTHYOMANCY: Very popular in cultures which depend upon fish for existence, this is divination by the examination of the entrails of a fish. KLEIDOMANCY: By suspending a pendulum over an alphabet and asking questions, the pendulum is supposed to spell out the answers. A cousin to this skill today is the modem Ouija board. LECANOMANCY: One of the most beautiful and most expensive of the divinatory arts, gems are dropped into still pools of water and the ripples they create are analyzed for hints about the future. MOLYBDOMANCY: This is divination by observing the pattern formed by molten lead after it has been dropped onto a smooth surface. NUMEROLOGY: A very popular form of divination for the last hundred years or so, this art analyzes numbers connected to a person''s name and date of birth, using a very stringent system for reducing alphabetical names to numbers. PESSOMANCY: This is divination by observing the size, shape, texture, etc., of a pebble drawn randomly from a pile. PHYLLORHODOMANCY: Taking literally the old saw that each flower carries a message, this technique analyzes the pattern formed by the petals and leaves of a rose to divine the future. PYROMANCY: According to the practitioners of this technique, by analyzing a fire, paying special attention to the flames and any smoke or sparks, the future can be told. TASSEOGRAPHY: This is the reading of tea leaves; a specialty of old women in tea houses and restaurants around the world. XYLOMANCY: This technique analyzes the pattern of spikes thrown on the ground. Somewhat related to Belomancy, the best known example of this system is the Chinese "I Ching," or Book of Changes, system.', NULL),
  ('Mediumship/Clairsentience', 'Sensitive', 4, NULL, NULL, 'import', 'Nightbane RPG p.74-75', 'nightbane', 'Self', '2D4 minutes (plus 3D4 minutes of preparation)', NULL, 'Some individuals are especially sensitive to psychic impressions and can open themselves to the supernatural forces. The clairsentience power operates on two levels. First: The psychic sensitive acts as a beacon, calling out to haunting ghosts or other entities. This makes the psychic''s presence known, as well as invites the entity(s) to come forth and communicate. Second, the psychic acts as a medium through which the entity can speak (temporary possession) or as the mediator (the person who asks the questions). As the mediator of a seance group, someone other than the psychic beacon is temporarily possessed, but only the mediator can ask questions. The spirit or entity will temporarily enter the medium or psychically susceptible member of a seance group to communicate. The voice is often the voice of the spirit force, not the person, and might be in a foreign language. The entity may not speak at all, but write or draw its message. Communications are usually brief, seldom lasting more than five minutes and ending abruptly. The entity is not bound to answer questions truthfully, although good alignments have no reason to lie (evil entities lie freely). The person selected as the "mouthpiece" will remember nothing that occurred while possessed. If the person has latent psychic powers or many P.P.E. points, the possessing force will be able to draw on that energy reserve to create other phenomena such as telekinesis, empathic transfer, etc. The spirit''s words and actions can not be controlled, making physical manifestations all the more frightening. This accounts for gusts of wind, rapping, table movement, etc. Fortunately, the possession is short-lived, or contact can be broken by breaking the chain in the seance. The seance chain is composed of a group of people who sit, holding each other''s hands to create a circle. The group can be a mere two people or as many as a dozen. It is pointless for the psychic medium to open himself up to a seance without at least one other, because he can not remember what happens while under the control of the entity. Another reason for having several people is that each person can feed the medium with their own potential psychic energy (P.P.E.). Each person in the seance chain can temporarily contribute up to half of his/her P.P.E. to the cause. The only requirement is to truly desire communication with a supernatural force. Each supporter of the communication link adds P.P.E. fuel. Each P.P.E. point increases the bases skill by +2%. The psychic medium can draw on all of his P.P.E. points, which is usually 8 or 10. Every P.P.E. point from a person opposed to the communication reduces the success ratio by -2%. A nega-psychic who is a member of a seance chain will reduce the success by -4% per each of his P.P.E. points. However, the nega-psychic can observe a seance without any ill effects. The use of the P.P.E. energies is momentary and returns to full level within minutes, but may leave some participants with a slight feeling of dizziness or fatigue for those few minutes. The seance can be broken at any time by letting go of each other''s hands. Game Master''s Note: The behavior of the ghost or entity that communicates through the medium will depend on the type of entity, its alignment and its plans. Many haunting ghosts want help if they can get it, while poltergeists are pure mischief. The more powerful, evil entities may mislead or mock the characters, or even lash out during a seance, using the participants'' own P.P.E. against them. However, a seance assault is usually more frightening than deadly. The spirit force can communicate in voice, writing, symbols/drawings, or sometimes with telepathy or empathic transfer as well. A brief gust of wind often whips up out of nowhere, small objects are knocked over or rattle about, the table may move or levitate as much as two feet above the floor and another psychic may sense the entity''s emotions. The most sensational and violent seances may produce hurling objects which can inflict minor physical damage to the seance participants, ectoplasmic apparitions, empathic transmissions (usually fear, confusion or despair) and even magic spells/assaults. Regardless of the strength and ferocity of the creature''s response/onslaught, the seance can always be instantly stopped by just one person breaking the chain of holding hands. The moment somebody lets go, the mini-circle of P.P.E. power is broken and the entity is dispelled from the host medium''s body. At that same instant, all physical and mental manifestations cease. In the case of non-psychic seance attempts (ordinary people without the aid of a professional psychic or medium), the base skill is equal to the number of P.P.E. points linked by the hand holding. The person with the most P.P.E. or one with latent psychic abilities is the likely one to be selected by the entity to communicate through.', NULL),
  ('Induce Pain', 'Healing', 2, '2 per minute', NULL, 'import', 'Nightbane RPG p.83-84', 'nightbane', 'Touch or within 6 feet (1.8 m).', 'As long as the trance is maintained.', 'Standard', 'The ability to inflict a terrible, debilitating pain without physically damaging the living creature. Victims are -6 to strike, parry and dodge, lose initiative, skills are -30%, and attacks per melee are half. There is a good chance of the victim passing out after five minutes of continuous pain; 50%+10% per each additional minute.', NULL);

-- Read the result back. This batch asserts its OWN rows and nothing else.
SELECT 'three nightbane powers inserted' AS assertion, count(*) AS got, 3 AS want
  FROM psionic_powers WHERE system = 'nightbane' AND source_book LIKE 'Nightbane RPG p.%';

SELECT 'each in its category at its cost' AS assertion, count(*) AS got, 3 AS want
  FROM psionic_powers WHERE system = 'nightbane'
   AND ((name = 'Divination' AND category = 'Sensitive' AND isp = 3)
     OR (name = 'Mediumship/Clairsentience' AND category = 'Sensitive' AND isp = 4)
     OR (name = 'Induce Pain' AND category = 'Healing' AND isp = 2 AND isp_note = '2 per minute'));

SELECT 'every one carries its full description' AS assertion, count(*) AS got, 3 AS want
  FROM psionic_powers WHERE system = 'nightbane' AND length(description) > 200;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('zzzzzzzzzzzzz-nb-psionics.sql');
